const inr = new Intl.NumberFormat("en-IN", { style: "currency", currency: "INR", maximumFractionDigits: 0 });
const inrExact = new Intl.NumberFormat("en-IN", { style: "currency", currency: "INR", minimumFractionDigits: 2 });

/** Format paise as ₹ with Indian digit grouping. */
export function formatINR(paise: number, exact = false) {
  return (exact ? inrExact : inr).format(paise / 100);
}

export function rupeesToPaise(rupees: number | string) {
  return Math.round(Number(rupees) * 100);
}

export function discountPercent(price: number, mrp: number) {
  if (!mrp || mrp <= price) return 0;
  return Math.round(((mrp - price) / mrp) * 100);
}

/** GST component contained in a GST-inclusive amount. */
export function gstIncluded(amount: number, ratePercent: number) {
  return Math.round(amount - amount / (1 + ratePercent / 100));
}

/** Standard reducing-balance EMI. Returns monthly instalment in paise. */
export function emiMonthly(principal: number, annualRatePercent: number, months: number) {
  if (annualRatePercent === 0) return Math.ceil(principal / months);
  const r = annualRatePercent / 12 / 100;
  return Math.ceil((principal * r * (1 + r) ** months) / ((1 + r) ** months - 1));
}

